import { Injectable } from '@angular/core';
import {
  HttpRequest,
  HttpHandler,
  HttpEvent,
  HttpInterceptor,
  HttpErrorResponse
} from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { AuthService } from '../services/auth.service';

@Injectable()
export class HttpConfigInterceptor implements HttpInterceptor {
  constructor(private authService: AuthService) {}

  intercept(request: HttpRequest<unknown>, next: HttpHandler): Observable<HttpEvent<unknown>> {
    // Obter token do localStorage
    const token = localStorage.getItem('token');
    
    console.log('🔐 Interceptor chamado!', {
      url: request.url,
      token_exists: !!token,
      token_length: token?.length || 0
    });

    // Se houver token, adicionar ao header Authorization
    if (token) {
      console.log('✅ Adicionando Authorization header:', `Bearer ${token.substring(0, 20)}...`);
      request = request.clone({
        setHeaders: {
          Authorization: `Bearer ${token}`
        }
      });
    } else {
      console.warn('⚠️ Sem token no localStorage!');
    }

    return next.handle(request).pipe(
      catchError((error: HttpErrorResponse) => {
        console.error('❌ Erro na requisição:', error.status, error.statusText);
        // Se receber 401, fazer logout
        if (error.status === 401) {
          this.authService.logout();
        }
        return throwError(() => error);
      })
    );
  }
}
